package com.skutracker.logic

import com.skutracker.model.SKUItem

class CashReturnCalculator {

    /**
     * Calculates monthly cash-on-cash return per 1,000 RS invested.
     * Formula: (Monthly Net Profit generated by SKU / Total Capital Invested) * 1000
     */
    fun calculateCashReturnPer1000(item: SKUItem): Double {
        if (item.capitalInvested <= 0.0) return 0.0
        
        val profitPerUnit = item.sellingPricePerUnit - item.costPricePerUnit
        val totalMonthlyNetProfit = profitPerUnit * item.monthlyUnitsSold
        
        return (totalMonthlyNetProfit / item.capitalInvested) * 1000.0
    }

    /**
     * Flags whether an SKU is moving at a slow monthly velocity.
     * Threshold can be customized (e.g., fewer than 5 units sold a month).
     */
    fun isSlowMoving(item: SKUItem, velocityThreshold: Int = 5): Boolean {
        return item.monthlyUnitsSold < velocityThreshold
    }
}